import { Annotation, Command, StateGraph, START, END } from "@langchain/langgraph";

const State = Annotation.Root({
  value: Annotation<number>(),
  next: Annotation<string>(),
});

const route = (state: typeof State.State): Command<"finish"> => {
  if (state.value > 0) {
    return new Command({ update: { next: "finish" }, goto: "finish" });
  }
  return new Command({ update: { next: "finish" }, goto: END });
};

const finish = (state: typeof State.State) => ({
  value: state.value + 1,
});

const graph = new StateGraph(State)
  .addNode("route", route)
  .addNode("finish", finish)
  .addEdge(START, "route")
  .addEdge("finish", END)
  .compile();

await graph.invoke({ value: 1, next: "" });

