import { trimMessages } from "@langchain/core/messages";
import { StateSchema, MessagesValue, GraphNode } from "@langchain/langgraph";

const State = new StateSchema({ messages: MessagesValue });

const callModel: GraphNode<typeof State> = async (state) => {
  const messages = trimMessages(state.messages, {
    strategy: "last",
    maxTokens: 128,
    startOn: "human",
    endOn: ["human", "tool"],
  });
  const response = await model.invoke(messages);
  return { messages: [response] };
};

from langchain_core.documents import Document
from langchain_core.vectorstores import InMemoryVectorStore

class SimpleEmbeddings:
    def embed_documents(self, texts):
        return [[float(len(text))] for text in texts]

    def embed_query(self, text):
        return [float(len(text))]

store = InMemoryVectorStore(SimpleEmbeddings())
store.add_documents([
    Document(page_content="Red apple", metadata={"source": "fruit"}),
    Document(page_content="Blue car", metadata={"source": "vehicle"}),
], ids=["fruit-1", "vehicle-1"])

results = store.similarity_search(
    "yellow fruit", k=1, filter={"source": "fruit"}
)
print(results[0].page_content)
